/**
 * Lightweight UI localization.
 *
 * The application is English by default and can switch to the major
 * international languages plus Thai. Translations are plain string maps keyed
 * by stable identifiers; missing keys fall back to English so the UI never
 * renders an empty label. The current language is stored in the backend
 * settings and loaded once at startup.
 */

import { createContext, useContext } from "react";

export const LANGUAGES = [
  { code: "en", label: "English", nativeName: "English" },
  { code: "th", label: "ไทย", nativeName: "ไทย" },
  { code: "zh", label: "简体中文", nativeName: "简体中文" },
  { code: "ja", label: "日本語", nativeName: "日本語" },
  { code: "ko", label: "한국어", nativeName: "한국어" },
  { code: "de", label: "Deutsch", nativeName: "Deutsch" },
  { code: "fr", label: "Français", nativeName: "Français" },
  { code: "es", label: "Español", nativeName: "Español" },
  { code: "ru", label: "Русский", nativeName: "Русский" },
] as const;

export type LanguageCode = (typeof LANGUAGES)[number]["code"];

